//===----------------------------------------------------------------------===//
//
// Declares the instruction printer that writes MC instructions as assembly
// text; the mnemonic tables are generated by TableGen.
//
//===----------------------------------------------------------------------===//

#ifndef LLVM_LIB_TARGET_MERA400_MCTARGETDESC_MERA400INSTPRINTER_H
#define LLVM_LIB_TARGET_MERA400_MCTARGETDESC_MERA400INSTPRINTER_H

#include "llvm/MC/MCInstPrinter.h"

namespace llvm {
class Mera400InstPrinter : public MCInstPrinter {
public:
  using MCInstPrinter::MCInstPrinter;
  void printRegName(raw_ostream &OS, MCRegister Reg) override;
  void printInst(const MCInst *MI, uint64_t Address, StringRef Annot,
                 const MCSubtargetInfo &STI, raw_ostream &OS) override;
  void printOperand(const MCInst *MI, unsigned OpNo, raw_ostream &OS);
  void printNormOperand(const MCInst *MI, unsigned OpNo, raw_ostream &OS);
  void printShortBrOperand(const MCInst *MI, unsigned OpNo, raw_ostream &OS);
  std::pair<const char *, uint64_t>
  getMnemonic(const MCInst &MI) const override;
  void printInstruction(const MCInst *MI, uint64_t Address, raw_ostream &OS);
  static const char *getRegisterName(MCRegister Reg);
};
} // namespace llvm

#endif
